class EventEmitter {
  constructor() { this._handlers = {}; }
  on(event, fn) {
    (this._handlers[event] ??= []).push(fn);
    return this;
  }
  emit(event, ...args) {
    (this._handlers[event] ?? []).forEach(fn => fn(...args));
  }
}
